import { delete_timesheet } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    timesheetdeletion: Boolean,
    timesheetitems: Object
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    timesheetdeletion: {
      async handler() {},
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(delete_timesheet, {
          input: {
            timesheet_id: this.timesheetitems.timesheet_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.delete_timesheet);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
